                    }
                    def stableLogs = process.out.log.collect { logTuple ->
                        [logTuple[0], path(logTuple[1]).getFileName().toString()]
                    }
                    assert snapshot(
                        stableMaster,
                        stableSnplists,
                        stableLogs,
                        process.out.findAll { key, val -> key.startsWith('versions') }
